(() => {
 const L=FRTB_LESSONS,F=FRTB,U=FRTB_UI,{slider,select,bars,m,n,pct}=U;
 const profiles={
  swap:['Vanilla interest-rate swap',['GIRR'],[],[],false,false,'Fixed and floating rate cash flows produce yield-curve delta. A vanilla swap has no embedded option; its rate convexity is not automatically mandatory SBM curvature.'],
  bond:['Corporate fixed-rate bond',['GIRR','CSR'],[],[],true,false,'Discount rates and issuer credit spreads both affect price. Issuer default is an additional jump, captured separately in DRC.'],
  option:['Vanilla equity option',['Equity','GIRR'],['Equity'],['Equity','GIRR'],true,false,'Equity delta, implied-volatility vega and nonlinear spot/rate revaluation enter SBM. Default of the underlying issuer can change the option value; DRC needs default revaluation.'],
  cds:['Single-name CDS',['CSR','GIRR'],[],[],true,false,'Spread and discounting sensitivities enter SBM. The reference-entity default payoff enters DRC, with sign depending on whether protection is bought or sold.'],
  fx:['Vanilla FX option',['FX','GIRR'],['FX'],['FX','GIRR'],false,false,'Exchange-rate and domestic/foreign yield-curve delta coexist with FX volatility and curvature. The derivative counterparty is a separate SA-CCR / CVA question.'],
  swaption:['Swaption',['GIRR'],['GIRR'],['GIRR'],false,false,'Option expiry and underlying swap maturity are separate vega dimensions; rate curvature comes from full curve shocks.'],
  commodity:['Commodity option',['Commodity','GIRR'],['Commodity'],['Commodity','GIRR'],false,false,'Commodity price, delivery and tenor basis belong in the factor map, along with discounting and commodity optionality.'],
  index:['Listed equity index option',['Equity','GIRR'],['Equity'],['Equity','GIRR'],true,false,'Look-through or a qualifying consistent index approach determines the equity map. DRC has its own look-through treatment.'],
  barrier:['OTC equity barrier option',['Equity','GIRR'],['Equity'],['Equity','GIRR'],true,true,'Barrier path dependence can leave other residual risk after ordinary sensitivities are captured; this OTC example assumes no RRAO exclusion.']
 };
 function tradeMap(s){const p=profiles[s.trade],foreign=s.currency==='foreign',delta=[...p[1],...(foreign&&!p[1].includes('FX')?['FX']:[])];return {profile:p,delta,vega:p[2],curvature:p[3],drc:p[4],rrao:p[5]};}
 window.FRTB_TRADE_MAP=tradeMap;
 const trade={id:'trade-capital',name:'Trade → Capital Explorer',stage:'01 · Foundations',title:'Follow a trade through the capital map',intro:'Choose a product and trace its market risk factors into SBM, default and residual-risk layers. One trade can appear in several places.',chart:'Which layers capture this trade?',inputs:[select('trade','Choose a trade',Object.entries(profiles).map(([k,p])=>[k,p[0]]),'bond'),select('currency','Currency of denomination',[['domestic','GBP · reporting currency'],['foreign','Foreign currency · value translated to GBP']],'domestic'),select('direction','Position',[['long','Long / receive fixed / buy protection'],['short','Short / pay fixed / sell protection']],'long'),select('route','Capital approach',[['sa','Standardised approach'],['ima','IMA · permitted and eligible desk assumed']],'sa')],challenge:'Compare a CDS with an FX option. Both face a counterparty, but do they create the same issuer default risk?',formula:'Trade → risk factors → Delta / Vega / Curvature + DRC + RRAO',key:'A highlighted layer indicates exposure to assess, not a strictly positive capital charge. Netting, position direction, valuation and exclusions still matter.',simpleTitle:'Map the source of loss, not just the product name',simple:'Think of a trade as a bundle of questions. Can rates change its value? Can its issuer default? Does its payoff depend on a path? The same position may need several answers, and hedging one answer does not settle the others.',scope:'Vanilla, non-securitised trading-book instruments except the named OTC barrier. No stochastic-rate volatility, quanto effects, repo or dividend risk in these simplified profiles. Optional products include rate curvature where the full revaluation has rate dependence. Foreign denomination adds FX translation delta; any material additional FX optionality needs instrument-level assessment.',pages:[[313,'325c–e · capital layers and scope'],[323,'325l–q · risk factors'],[335,'325u · residual risks'],[336,'325v–z · issuer default']],notes:[['Do not confuse issuer and counterparty default','FRTB DRC concerns the issuer / underlying default risk within its scope. Counterparty replacement exposure and counterparty spread risk belong to separate counterparty credit risk and CVA frameworks. See the SA-CCR and SA-CVA learning paths.'],['A zero number is not a missing risk','A long vanilla option can have negative CVR residuals and zero standalone curvature loss. A protection buyer can have short JTD. Those are outcomes after valuation and aggregation, not reasons to omit the relevant layer.'],['IMA is a different route','For a permitted eligible desk, modellable market factors feed liquidity-adjusted ES and NMRFs feed SSRM; issuer default feeds the internal DRC model where permitted. SA components remain relevant for fallback and benchmarking. The SA RRAO is not mechanically added to IMA ES.']],compute(s){const r=tradeMap(s),p=r.profile,components=[['Delta',r.delta.join(', ')],['Vega',r.vega.join(', ')],['Curvature',r.curvature.join(', ')],['DRC',r.drc?'Underlying / issuer default':'No issuer default exposure in this profile'],['RRAO',r.rrao?'Other residual risk · assess 0.1% gross notional':'None assumed for this plain payoff']];return {stats:[['Trade',p[0]],['SBM risk classes',String(new Set([...r.delta,...r.vega,...r.curvature]).size)],['Selected route',s.route.toUpperCase()]],bars:bars(['Delta','Vega','Curvature','DRC','RRAO'],[1,+!!r.vega.length,+!!r.curvature.length,+r.drc,+r.rrao]),headers:['Layer','Risk factors / treatment','Position implications'],rows:components.map(([k,v])=>[k,v||'No volatility / optionality in this profile',k==='DRC'?'Default revaluation and netting determine sign and charge':s.direction==='short'?'Short direction reverses signed sensitivities / revaluation P&L':'Long direction; sensitivities still depend on payoff']).concat([['IMA connection',s.route==='ima'?'Modellable ES + SSRM + internal DRC':'SA SBM + DRC + RRAO',s.route==='ima'?'Permission, RFET, data quality and desk tests remain necessary':'Choose a risk-class applet to calculate weighted sensitivities']]),explanation:p[6]+' '+(foreignText(s))+(s.route==='ima'?' Under the selected IMA route, market risks are assessed for ES or SSRM rather than charged by adding these SA indicator bars.':''),note:'Bars are applicability indicators (1 = layer to assess, 0 = absent under the stated assumptions), not capital amounts. Short positions may still require capital.'};}};
 function foreignText(s){return s.currency==='foreign'?'Foreign-currency valuation also needs FX translation risk in GBP.':'';}
 L.splice(1,0,trade);

 // The sandbox uses a narrow, explicit SA delta portfolio. It never reassigns an unchanged issuer to a cheaper bucket.
 function sandbox(s){const mode=s.mode,notional=s.size,hedge=s.hedge/100,base=[];let rows=[],baseline=0,cap=0,explanation='',scenarios=[],title='';
  if(mode==='netting'||mode==='maturity'){
   const t=s.tenor,ht=mode==='netting'?t:s.hedgeTenor,rho=mode==='netting'?(s.factor==='same'?1:.999):Math.max(Math.exp(-.03*Math.abs(t-ht)/Math.min(t,ht)),.4),rw=x=>(x===.25||x===.5?.017:x===1?.016:x===2?.013:x===3?.012:.011)/Math.SQRT2;
   // Sensitivities are supplied, held fixed: this isolates vertex weights/correlations, not trade repricing.
   const a=notional*rw(t),b=-notional*hedge*rw(ht);baseline=Math.abs(a);
   scenarios=['low','medium','high'].map(sc=>[sc,mode==='netting'&&s.factor==='same'?Math.abs(a+b):F.linearBucket([a,b],F.scenario(rho,sc))]);cap=Math.max(...scenarios.map(x=>x[1]));
   rows=[['Primary sensitivity',m(notional),t+'y GBP yield vertex'],['Hedge sensitivity',m(-notional*hedge),ht+'y GBP yield vertex'],['Risk weights',pct(rw(t))+' / '+pct(rw(ht)),'GBP √2 reduction applied'],['Base factor correlation',pct(rho),mode==='netting'&&s.factor==='same'?'Identical factor: net before weighting':'Distinct factors: correlation aggregation']];
   explanation=mode==='netting'?'Exact matching risk factors net even when trades have different counterparties; a legal SA-CCR netting set is not an SBM netting requirement. Changing to another curve leaves basis risk.':'The displayed sensitivities stay fixed while vertices change, isolating maturity mapping and correlation. Actual trade maturity changes also require recalculating sensitivities; shorter does not automatically mean a better hedge.';title='GIRR delta';
  }else if(mode==='mapping'){
   const financial=s.sector==='financial',rw=financial?.05:.03,a=notional*.05,b=-notional*hedge*rw,rho=financial?.35:.15;baseline=Math.abs(a);
   scenarios=['low','medium','high'].map(sc=>[sc,financial?F.linearBucket([a,b],F.scenario(rho,sc)):F.linearAggregate([{ws:[a],k:Math.abs(a)},{ws:[b],k:Math.abs(b)}],F.scenario(rho,sc)).capital]);cap=Math.max(...scenarios.map(x=>x[1]));
   rows=[['Primary issuer','IG financial · bucket 3','5% CSR delta weight'],['Hedge issuer',financial?'Another IG financial · bucket 3':'IG consumer / transport · bucket 5',pct(rw)+' CSR delta weight'],['Sensitivities',m(notional)+' / '+m(-notional*hedge),'Same 5y tenor and bond basis'],['Base correlation',pct(rho),financial?'Different issuer in same bucket':'Different sector, same rating quality']];title='CSR delta';explanation='The control substitutes a different hedge issuer with the stated sector; it does not relabel the original issuer. Bucket mapping follows real attributes. A lower hedge risk weight can even reduce its ability to offset the primary weighted exposure.';
  }else{
   // 20 equal constituents, all large-cap advanced economy consumer names: bucket 5.
   const a=notional*.30,h=notional*hedge*.30,count=20;baseline=F.linearBucket(Array(count).fill(a/count),.25);
   scenarios=['low','medium','high'].map(sc=>{const rho=F.scenario(.25,sc);return [sc,s.decompose==='lookthrough'?F.linearBucket(Array.from({length:count},(_,i)=>a/count-(i===0?h:0)),rho):F.linearBucket([a,-h],rho)]});cap=Math.max(...scenarios.map(x=>x[1]));
   const baselineSc=['low','medium','high'].map(sc=>s.decompose==='lookthrough'?F.linearBucket(Array(count).fill(a/count),F.scenario(.25,sc)):a);baseline=Math.max(...baselineSc);
   rows=[['Underlying index','20 equal names · 5% each','All map to equity bucket 5; total cap assumed £40bn'],['Concentration tests','Largest 5%; top ceil(20/10) = 10%','≤25% single-name and ≤60% top tenth'],['Single sensitivity route','30% weight in bucket 5','>75% same-bucket test means this is not the 15% index bucket'],['Look-through route','20 × '+m(notional/20),'Net the hedge only against its identical constituent'],['Hedge target',m(notional*hedge),'Short constituent #1 only; may overhedge that name']];title='Equity delta';explanation='Decomposition reveals which constituent the short actually hedges. In the single-sensitivity route the index is treated as a separate single-name factor in bucket 5 because all constituents map there. Routes must be consistent across instruments on the same index; switching from look-through requires PRA permission.';
  }
  return {capital:cap,baseline,scenarios,stats:[['Selected '+title,m(cap)],['Unhedged · same mapping',m(baseline)],['Change versus unhedged',m(cap-baseline)]],bars:bars(['Unhedged','Low','Medium','High'],[baseline,...scenarios.map(x=>x[1])]),headers:['Step','Input / result','Interpretation'],rows:rows.concat(scenarios.map(([sc,k])=>[sc+' correlation',m(k),'Calculate this scenario consistently']),[['Selected charge',m(cap),'Maximum of the three scenarios']]),explanation,note:'Only the named delta component is calculated. Vega, curvature, DRC, RRAO, trading costs and other bank capital requirements are excluded; this is not total capital or a recommendation.'};
 }
 window.FRTB_SANDBOX=sandbox;
 L.push({id:'optimisation',name:'Capital Optimisation Sandbox',stage:'09 · Portfolio experiments',title:'Change the hedge. Explain the capital impact.',intro:'Explore exact-factor netting, maturity mismatch, rule-based bucket mapping and index decomposition in a transparent SA portfolio.',chart:'Unhedged baseline and three correlation scenarios',inputs:[select('mode','Experiment',[['netting','1 · Exact netting vs curve basis'],['maturity','2 · Maturity / vertex mismatch'],['mapping','3 · Hedge issuer and bucket mapping'],['index','4 · Index decomposition']],'netting'),slider('size','Primary raw sensitivity',0,200,5,100,'£m'),slider('hedge','Hedge size / primary sensitivity',0,150,5,50,'%'),{...select('factor','Hedge risk factor',[['same','Identical curve and vertex'],['other','Different curve · same currency / vertex']],'same'),when:s=>s.mode==='netting'},...['tenor','hedgeTenor'].map((id,i)=>({...select(id,i?'Hedge vertex':'Primary vertex',[.25,.5,1,2,3,5,10,15,20,30].map(t=>[String(t),t+' years']),'5'),when:s=>s.mode==='maturity'||(!i&&s.mode==='netting')})),{...select('sector','Replace hedge issuer with',[['financial','IG financial issuer'],['consumer','IG consumer / transport issuer']],'financial'),when:s=>s.mode==='mapping'},{...select('decompose','Consistent index treatment',[['lookthrough','Look through to all 20 constituents'],['single','Eligible single sensitivity · permission assumed']],'lookthrough'),when:s=>s.mode==='index'}],challenge:'Match the hedge to 100%, then move it to a different vertex or curve. Where does the apparent perfect hedge go?',formula:'Net identical factors → weight → aggregate each scenario → take the largest',key:'Raw rate/spread sensitivities are per 1.00 absolute move; spot sensitivity is spot × ∂V/∂spot. Do not enter DV01 or CS01 without converting their basis-point units.',simpleTitle:'Useful capital changes need an economic explanation',simple:'A smaller charge can reflect a more precise hedge, a different exposure or a permitted treatment. The calculation trace helps distinguish them. Neither bucket labels nor index treatment can be changed freely to obtain the smallest number.',scope:'Each experiment isolates one delta risk class. Sensitivities are controlled inputs and are not automatically recalculated from a trade. The equity index is listed, has known equal weights, 20 names and £40bn total capitalisation. All are bucket-5 equities. All other index eligibility and permission conditions are assumed.',pages:[[315,'325f · netting and aggregation'],[318,'325h · scenario maximum'],[319,'325i · index conditions'],[343,'325ae–ag · GIRR weights and correlations'],[345,'325ah–aj · CSR mapping'],[354,'325ap–ar · equity mapping']],compute(s){return sandbox({...s,tenor:+s.tenor,hedgeTenor:+s.hedgeTenor})}});
})();
